#include <iostream>
using namespace std;

int main(){
    int N, S, D;
    cin >> N >> S >> D;
    for(int i = 0; i < N; i++){
        int X, Y;
        cin >> X >> Y;
        if(X < S && Y > D){
            puts("Yes");
            return 0;
        }
    }
    puts("No");
}

N, S, D = map(int, input().split())
def check():
    X, Y = map(int, input().split())
    return X < S and Y > D

if any(check() for i in range(N)):
    print("Yes")
else:
    print("No")
